async ({ workspace: { read, search }, git: { status, log } }) => {
  const [skill, st, lg, hits] = await Promise.all([
    read(".pi/skills/pit-delivery/SKILL.md", { format: "raw" }),
    status(["--short", "--branch"]),
    log(["--oneline", "-8"]),
    search("defineTool", { path: "src", limit: 20, contextLines: 0 }),
  ]);
  return { skill: skill.content, st: st.stdout, lg: lg.stdout, hits: hits.matches?.map((m: any) => `${m.file}:${m.line} ${m.text}`) ?? hits };
}
